/**
 * Typed API client.
 *
 * `paths` comes from `src/api/schema.ts`, generated by `npm run generate:api`
 * from the shared contract `docs/openapi.yaml` (API Platform 4).
 *
 * ── Content negotiation ────────────────────────────────────────────────────
 * The backend serves every resource in two flavours:
 *   - `application/ld+json` → JSON-LD / Hydra envelope (`member`, `totalItems`)
 *   - `application/json`    → bare array, no pagination metadata
 *
 * We commit to **application/ld+json**: pagination metadata is required for the
 * catalogue's infinite scroll. That choice is pinned in the type system through
 * the second generic of `createClient`, so `data` is the Hydra shape and never
 * a union of both — and the `Accept` header matches what the types claim.
 */
import createClient, { type Middleware } from 'openapi-fetch'
import type { paths } from './schema'
import { API_BASE_URL } from '../config'
import { getSession, isTokenExpired, notifyUnauthorized, setSession } from '../auth/session'

/** The single media type this app speaks. Keep the header and the generic in sync. */
export const MEDIA_TYPE = 'application/ld+json'

export const apiClient = createClient<paths, typeof MEDIA_TYPE>({
  baseUrl: API_BASE_URL,
  headers: { Accept: MEDIA_TYPE },
})

/**
 * Second client, pinned to plain `application/json`, for the handful of
 * operations the contract does **not** serve as JSON-LD.
 *
 * `POST /api/login` is the only one today: it declares `application/json`
 * exclusively, so asking `apiClient` for it yields `never` — the media type it
 * is pinned to simply is not in that operation's response map.
 *
 * It deliberately carries **no auth middleware**: login must never be able to
 * trigger the global "session expired" logout, and it has no token to send.
 */
export const jsonApiClient = createClient<paths, 'application/json'>({
  baseUrl: API_BASE_URL,
  headers: { Accept: 'application/json' },
})

/**
 * Auth middleware — the single place where the JWT enters the request, and the
 * single place where a 401 is turned into a logout. No call site knows about
 * authentication.
 *
 * Two guards keep the "expired token" path from looping:
 *
 *  1. `onRequest` refuses to send an already-expired token: it clears the
 *     session locally instead. So we do not even generate the 401.
 *  2. `onResponse` only reacts when the request actually carried a token, and
 *     `notifyUnauthorized()` is itself idempotent (it no-ops once the session
 *     is gone). A burst of parallel 401s therefore triggers exactly one logout.
 *
 * `AUTH_PATHS` is belt-and-braces: those requests normally carry no token, so
 * guard 2 already skips them, but an authenticated user re-submitting the
 * login form must never be logged out by their own typo.
 */
const AUTH_PATHS = ['/api/login', '/api/register']

const authMiddleware: Middleware = {
  onRequest({ request }) {
    const session = getSession()
    if (!session) return request

    if (isTokenExpired(session.token)) {
      // Guard 1: locally expired. Drop it silently; the caller will simply get
      // the anonymous response. `setSession` (not `notifyUnauthorized`) because
      // this is not a server rejection and needs no redirect of its own —
      // `AuthProvider` re-renders and the protected routes bounce naturally.
      setSession(null)
      return request
    }

    request.headers.set('Authorization', `Bearer ${session.token}`)
    return request
  },

  onResponse({ request, response }) {
    if (response.status !== 401) return response
    // Guard 2: only an *authenticated* request that got rejected means the
    // token died. A 401 on an anonymous request is just a protected endpoint.
    if (!request.headers.has('Authorization')) return response
    if (AUTH_PATHS.some((path) => new URL(request.url).pathname.endsWith(path))) return response

    notifyUnauthorized()
    return response
  },
}

apiClient.use(authMiddleware)

/** Thrown when the API answers with a non-2xx status. */
export class ApiError extends Error {
  readonly status?: number

  constructor(message: string, status?: number) {
    super(message)
    this.name = 'ApiError'
    this.status = status
  }
}

/**
 * Turns an API Platform `detail` into something safe to put in front of a user.
 *
 * The backend leaks raw Doctrine/PostgreSQL errors on some failures — a
 * duplicate favourite currently answers **500** with the full
 * `SQLSTATE[23505] … duplicate key value violates unique constraint` message
 * and a stack trace (observed against the running backend, reported upstream).
 * Rendering that verbatim would be both unreadable and an information leak, so
 * the known cases are translated and anything else DB-shaped is genericised.
 * The original stays in the console for whoever is debugging.
 */
function humanizeDetail(detail: string, status: number): string {
  if (/duplicate key|unique constraint|already exists/i.test(detail)) {
    return 'Cet élément existe déjà.'
  }
  if (/SQLSTATE|An exception occurred while executing/i.test(detail)) {
    console.warn('[api] Erreur base de données renvoyée telle quelle par le backend :', detail)
    return `Le serveur a rencontré une erreur (${status}).`
  }
  // Long details are almost always stack traces or dumps, not user-facing prose.
  return detail.length > 300 ? `Le serveur a rencontré une erreur (${status}).` : detail
}

/**
 * Unwraps an `openapi-fetch` result, throwing on error so React Query can
 * handle failures through its normal error state. API Platform returns RFC 7807
 * style errors, whose human-readable field is `detail`.
 */
export function unwrap<T>(result: { data?: T; error?: unknown; response: Response }): T {
  if (result.error || result.data === undefined) {
    const { status } = result.response
    const raw =
      typeof result.error === 'object' && result.error !== null && 'detail' in result.error
        ? String((result.error as { detail: unknown }).detail)
        : null
    throw new ApiError(raw ? humanizeDetail(raw, status) : `La requête a échoué (${status}).`, status)
  }
  return result.data
}
